ask_date($tanggal) ?><br><?= htmlspecialchars(spk_task_value('Jabatan Penandatangan', 'Project Manager')) ?><div class="space"></div><strong><?= htmlspecialchars(spk_task_value('Penandatangan', 'Project Manager')) ?></strong></div><div class="actions"><button onclick="window.print()">Cetak Surat</button></div></main></body></html>
